import { ok, fail } from './result.js';
import { getCustomer } from './customers.js';
import { getProduct } from './catalogue.js';
import { roundCents } from './money.js';
import { nextInvoiceNumber } from './numbering.js';

/**
 * Validate that issueDate is in YYYY-MM-DD format and is a real date.
 * @param {string} dateStr
 * @returns {boolean}
 */
function isValidDate(dateStr) {
  if (typeof dateStr !== 'string') return false;
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dateStr);
  if (!m) return false;
  const [, year, month, day] = m;
  try {
    const d = new Date(`${year}-${month}-${day}T00:00:00Z`);
    return d.toISOString().startsWith(dateStr);
  } catch {
    return false;
  }
}

/**
 * Create an invoice from a customer id, issue date, and line items.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }} input
 * @returns {import('./result.js').Result<{ customerId: string, issueDate: string, status: 'draft', lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> }>}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return customerResult;

  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  if (!lines || lines.length === 0) return fail('NO_LINES');

  const invoiceLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const { name, unitPrice, vatRate } = productResult.value;
    invoiceLines.push({
      sku: line.sku,
      name,
      qty: line.qty,
      unitPrice,
      vatRate,
    });
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
  });
}

/**
 * Calculate the total amount for a single line (qty × unitPrice).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {import('./result.js').Result<number>}
 */
export function lineTotal(line) {
  if (!line || typeof line.qty !== 'number' || typeof line.unitPrice !== 'number') {
    return fail('LINE_INVALID');
  }
  return ok(roundCents(line.qty * line.unitPrice));
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number }> }} invoice
 * @returns {import('./result.js').Result<{ subtotal: number, total: number }>}
 */
export function invoiceTotals(invoice) {
  if (!invoice || !Array.isArray(invoice.lines) || invoice.lines.length === 0) {
    return fail('INVOICE_INVALID');
  }

  let subtotal = 0;
  for (const line of invoice.lines) {
    const result = lineTotal(line);
    if (!result.ok) return result;
    subtotal += result.value;
  }

  return ok({
    subtotal: roundCents(subtotal),
    total: roundCents(subtotal),
  });
}

/**
 * Add a line to an invoice, or increase qty if the SKU already exists.
 * @param {{ status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> }} invoice
 * @param {{ sku: string, qty: number }} input
 * @returns {import('./result.js').Result<{ status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> }>}
 */
export function addLine(invoice, { sku, qty }) {
  if (!invoice || invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const { name, unitPrice, vatRate } = productResult.value;

  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingIndex >= 0) {
    newLines[existingIndex].qty += qty;
  } else {
    newLines.push({
      sku,
      name,
      qty,
      unitPrice,
      vatRate,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice by SKU.
 * @param {{ status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> }} invoice
 * @param {string} sku
 * @returns {import('./result.js').Result<{ status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> }>}
 */
export function removeLine(invoice, sku) {
  if (!invoice || invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((_, index) => index !== lineIndex);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue an invoice, assigning it a number and changing status to 'issued'.
 * @param {{ status: string, issueDate: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> }} invoice
 * @param {Array<string>} existingNumbers
 * @returns {import('./result.js').Result<{ status: string, number: string, issueDate: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> }>}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (!invoice || invoice.status !== 'draft') return fail('NOT_DRAFT');

  const numberResult = nextInvoiceNumber(existingNumbers, invoice.issueDate);
  if (!numberResult.ok) return numberResult;

  return ok({
    ...invoice,
    number: numberResult.value,
    status: 'issued',
  });
}

